package com.fream.back.domain.m64.service.command;

import com.fream.back.domain.m52.entity.Xrv73;
import com.fream.back.domain.m52.entity.Xbp24Type;
import com.fream.back.domain.m52.service.command.Xbp24CommandService;
import com.fream.back.domain.m99.entity.Xhq12;
import com.fream.back.domain.m99.entity.Xtw92;
import com.fream.back.domain.m64.dto.Xkg34RequestDto;
import com.fream.back.domain.m64.dto.Xxf47RequestDto;
import com.fream.back.domain.m64.dto.Xgg74RequestDto;
import com.fream.back.domain.m64.dto.Xjt45RequestDto;
import com.fream.back.domain.m64.entity.*;
import com.fream.back.domain.m64.exception.*;
import com.fream.back.domain.m64.p02.Xhs91ApiClient;
import com.fream.back.domain.m64.repository.Xjt45Repository;
import com.fream.back.domain.m64.service.query.Xjt45InfoQueryService;
import com.fream.back.domain.m85.entity.Xpj42;
import com.fream.back.domain.m85.entity.Xzt63;
import com.fream.back.domain.m85.entity.Xpj42Status;
import com.fream.back.domain.m85.service.query.Xzt63QueryService;
import com.fream.back.domain.m22.entity.Xjm45;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Duration;
import java.time.Instant;
import java.util.Map;





@Service
@RequiredArgsConstructor
@Transactional
@Slf4j
public class Xjt45CommandService {

    private final Xjt45Repository paymentRepository;
    private final Xjt45InfoQueryService paymentInfoQueryService;
    private final Xhs91ApiClient portOneApiClient;
    private final Xbp24CommandService notificationCommandService;
    private final Xzt63QueryService saleBidQueryService;











    public Xjt45 processPayment(Xhq12 order, Xjm45 user, Xjt45RequestDto requestDto) {
        Instant start = Instant.now();
        try {
            validatePaymentRequest(order, user, requestDto);

            log.info("결제 처리 시작: 주문ID={}, 사용자={}, 결제유형={}",
                    order.getId(), user.getEmail(), requestDto.getResolvedPaymentType());

            Xjt45 payment;

            switch (requestDto.getResolvedPaymentType()) {
                case "CARD":
                    payment = createCardPayment(order, user, (Xxf47RequestDto) requestDto);
                    break;
                case "ACCOUNT":
                    payment = createAccountPayment(order, user, (Xkg34RequestDto) requestDto);
                    break;
                case "GENERAL":
                    payment = createGeneralPayment(order, user, (Xgg74RequestDto) requestDto);
                    break;
                default:
                    throw new Xjt45Exception(Xjt45ErrorCode.PAYMENT_VALIDATION_FAILED,
                            "유효하지 않은 결제 유형: " + requestDto.getPaymentType());
            }


            notifyUsersAndUpdateSaleStatus(order, payment);

            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), payment.getId(), payment.getStatus());

            return payment;
        } catch (Xjt45Exception e) {
            log.error("결제 처리 실패: 주문ID={}, 사용자={}, 에러코드={}, 메시지={}",
                    order != null ? order.getId() : "null",
                    user != null ? user.getEmail() : "null",
                    e.getErrorCode().getCode(), e.getMessage());
            throw e;
        } catch (Exception e) {
            log.error("결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 사용자={}, 오류={}",
                    order != null ? order.getId() : "null",
                    user != null ? user.getEmail() : "null",
                    e.getMessage(), e);
            throw new Xtc14Exception("결제 처리 중 오류가 발생했습니다: " + e.getMessage());
        } finally {

            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("결제 처리 총 소요 시간: {}ms", duration.toMillis());
        }
    }









    private void validatePaymentRequest(Xhq12 order, Xjm45 user, Xjt45RequestDto requestDto) {
        if (order == null) {
            throw new Xjt45Exception(Xjt45ErrorCode.PAYMENT_PROCESSING_FAILED, "주문 정보가 없습니다.");
        }

        if (user == null) {
            throw new Xjt45Exception(Xjt45ErrorCode.PAYMENT_PROCESSING_FAILED, "사용자 정보가 없습니다.");
        }

        if (requestDto == null) {
            throw new Xjt45Exception(Xjt45ErrorCode.PAYMENT_VALIDATION_FAILED, "결제 요청 정보가 없습니다.");
        }


        if (!order.getId().equals(requestDto.getOrderId())) {
            throw new Xjt45Exception(Xjt45ErrorCode.PAYMENT_VALIDATION_FAILED,
                    "주문 ID가 일치하지 않습니다. 요청ID: " + requestDto.getOrderId() + ", 실제ID: " + order.getId());
        }

        if (!user.getEmail().equals(requestDto.getUserEmail())) {
            throw new Xjt45Exception(Xjt45ErrorCode.PAYMENT_VALIDATION_FAILED,
                    "사용자 이메일이 일치하지 않습니다. 요청이메일: " + requestDto.getUserEmail() + ", 실제이메일: " + user.getEmail());
        }


        if (requestDto.getPaidAmount() <= 0) {
            throw new Xjt45Exception(Xjt45ErrorCode.INVALID_PAYMENT_AMOUNT,
                    "결제 금액은 0보다 커야 합니다. 금액: " + requestDto.getPaidAmount());
        }
    }










    private Xjt45 createCardPayment(Xhq12 order, Xjm45 user, Xxf47RequestDto requestDto) {
        Instant start = Instant.now();
        try {
            log.info("카드 결제 처리 시작: 주문ID={}, 결제정보ID={}",
                    order.getId(), requestDto.getPaymentInfoId());


            Xjt45Info paymentInfo;
            try {
                paymentInfo = paymentInfoQueryService.getPaymentInfoEntity(user.getEmail(), requestDto.getPaymentInfoId());
                if (paymentInfo == null) {
                    throw new Xgs30Exception("결제 정보 ID: " + requestDto.getPaymentInfoId() + "를 찾을 수 없습니다.");
                }
            } catch (Xjt45Exception e) {
                throw e;
            } catch (Exception e) {
                throw new Xgs30Exception("결제 정보 조회 중 오류가 발생했습니다.", e);
            }


            Map<String, Object> response;
            try {
                response = portOneApiClient.processCardPayment(paymentInfo, requestDto.getPaidAmount());
            } catch (Xjt45Exception e) {
                throw e;
            } catch (Exception e) {
                throw new Xjt45ApiException("카드 결제 요청 중 오류가 발생했습니다: " + e.getMessage());
            }


            Xxf47 cardPayment = Xxf47.builder()
                    .cardNumber(paymentInfo.getCardNumber())
                    .cardPassword(paymentInfo.getCardPassword())
                    .cardExpiration(paymentInfo.getExpirationDate())
                    .birthDate(paymentInfo.getBirthDate())
                    .cardType((String) response.get("card_name"))
                    .paidAmount(requestDto.getPaidAmount())
                    .impUid((String) response.get("imp_uid"))
                    .receiptUrl((String) response.get("receipt_url"))
                    .pgProvider((String) response.get("pg_provider"))
                    .pgTid((String) response.get("pg_tid"))
                    .build();

            cardPayment.assignOrder(order);
            cardPayment.assignUser(user);

            if ("success".equals(response.get("status"))) {
                cardPayment.updateStatus(Xjt45Status.PAID);
                cardPayment.updateSuccessStatus(true);
            }

            Xxf47 savedPayment = (Xxf47) paymentRepository.save(cardPayment);
            log.info("카드 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), savedPayment.getId(), savedPayment.getStatus());


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("카드 결제 처리 시간: {}ms", duration.toMillis());

            return savedPayment;
        } catch (Xjt45Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("카드 결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 오류={}",
                    order.getId(), e.getMessage(), e);
            throw new Xtc14Exception("카드 결제 처리 중 오류가 발생했습니다: " + e.getMessage());
        }
    }










    private Xjt45 createAccountPayment(Xhq12 order, Xjm45 user, Xkg34RequestDto requestDto) {
        Instant start = Instant.now();
        try {
            log.info("계좌이체 결제 처리 시작: 주문ID={}, 은행={}",
                    order.getId(), requestDto.getBankName());


            try {
                validateBank(requestDto.getBankName());
            } catch (Exception e) {
                throw new Xjt45Exception(Xjt45ErrorCode.INVALID_BANK_INFO,
                        "유효하지 않은 은행 정보: " + requestDto.getBankName());
            }

            Xkg34 accountPayment = Xkg34.builder()
                    .bankName(requestDto.getBankName())
                    .accountNumber(requestDto.getAccountNumber())
                    .accountHolder(requestDto.getAccountHolder())
                    .receiptRequested(requestDto.isReceiptRequested())
                    .paidAmount(requestDto.getPaidAmount())
                    .build();

            accountPayment.assignOrder(order);
            accountPayment.assignUser(user);
            accountPayment.updateStatus(Xjt45Status.PENDING);

            Xkg34 savedPayment = (Xkg34) paymentRepository.save(accountPayment);
            log.info("계좌이체 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), savedPayment.getId(), savedPayment.getStatus());


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("계좌이체 결제 처리 시간: {}ms", duration.toMillis());

            return savedPayment;
        } catch (Xjt45Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("계좌이체 결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 오류={}",
                    order.getId(), e.getMessage(), e);
            throw new Xtc14Exception("계좌이체 결제 처리 중 오류가 발생했습니다: " + e.getMessage());
        }
    }










    private Xjt45 createGeneralPayment(Xhq12 order, Xjm45 user, Xgg74RequestDto requestDto) {
        Instant start = Instant.now();
        try {
            log.info("일반 결제 처리 시작: 주문ID={}, impUid={}",
                    order.getId(), requestDto.getImpUid());


            if (requestDto.getImpUid() == null || requestDto.getImpUid().isBlank()) {
                throw new Xjt45Exception(Xjt45ErrorCode.PAYMENT_VALIDATION_FAILED,
                        "결제 ID(impUid)는 필수 항목입니다.");
            }

            Xgg74 generalPayment = Xgg74.builder()
                    .impUid(requestDto.getImpUid())
                    .pgProvider(requestDto.getPgProvider())
                    .receiptUrl(requestDto.getReceiptUrl())
                    .buyerName(requestDto.getBuyerName())
                    .buyerEmail(requestDto.getBuyerEmail())
                    .paidAmount(requestDto.getPaidAmount())
                    .build();

            generalPayment.assignOrder(order);
            generalPayment.assignUser(user);
            generalPayment.updateSuccessStatus(true);
            generalPayment.updateStatus(Xjt45Status.PAID);

            Xgg74 savedPayment = (Xgg74) paymentRepository.save(generalPayment);
            log.info("일반 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), savedPayment.getId(), savedPayment.getStatus());


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("일반 결제 처리 시간: {}ms", duration.toMillis());

            return savedPayment;
        } catch (Xjt45Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("일반 결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 오류={}",
                    order.getId(), e.getMessage(), e);
            throw new Xtc14Exception("일반 결제 처리 중 오류가 발생했습니다: " + e.getMessage());
        }
    }







    private void handleRefundIfNecessary(Xjt45 payment) {
        Instant start = Instant.now();
        try {
            if (payment.getImpUid() == null || payment.getImpUid().isBlank()) {
                log.warn("환불 처리 불가: 결제ID={}, 결제식별자(impUid)가 없습니다.", payment.getId());
                return;
            }

            log.info("결제 환불 처리 시작: 결제ID={}, impUid={}", payment.getId(), payment.getImpUid());

            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());

            if (refundSuccess) {
                payment.updateStatus(Xjt45Status.REFUNDED);
                paymentRepository.save(payment);
                log.info("결제 환불 처리 완료: 결제ID={}, 상태=REFUNDED", payment.getId());
            } else {
                log.error("결제 환불 처리 실패: 결제ID={}", payment.getId());
                throw new Xjt45Exception(Xjt45ErrorCode.PAYMENT_CANCELLATION_FAILED,
                        "환불 요청이 실패했습니다. 관리자에게 문의하세요.");
            }


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("결제 환불 처리 시간: {}ms", duration.toMillis());
        } catch (Xjt45Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("결제 환불 처리 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
                    payment.getId(), e.getMessage(), e);
            throw new Xjt45Exception(Xjt45ErrorCode.PAYMENT_CANCELLATION_FAILED,
